idleProactiveReason() {
	const now = new Date();
	const hhmm = `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;
	const angles = [
		'手边正在做的事、这会儿在忙什么',
		'刚吃到的东西、忽然想吃的',
		'外面的天气、光线、声音',
		'白天碰到的一件小事、想吐槽的一句',
		'突然想起的、关于对方的一件旧事',
		'最近在追的剧、在玩的游戏、在听的东西',
		'自己身上的一点小状况：困、饿、冷、酸',
		'想去但一直没去的地方'
	];
	const pick = angles[Math.floor(Math.random() * angles.length)];
	return `好久没说话了（现在 ${hhmm}）。这次从一个新角度开口：${pick}。换个话题，别跟之前主动说过的话撞车`;
}

